const state = { period: '2026-T3', extraIndicators: [] }; const params = { high: 1, mid: .9, cap: 1.2 }; const $ = id => document.getElementById(id); const fmt = (n, d = 1) => Number.isFinite(n) ? n.toLocaleString('id-ID', { maximumFractionDigits: d, minimumFractionDigits: 0 }) : '—';
function kpiInfo(id) { return DATA.kpi_master.find(x => x.kpi_id === id) || state.extraIndicators.find(x => x.kpi_id === id) || { nama_kpi: id, satuan: '', arah: 'naik', bobot: 0, target_standar: 0, jabatan: '—' } }
function scoreRecord(r) { if (r.capaian === null || r.capaian === '' || r.target === null || !Number(r.target)) return null; let k = kpiInfo(r.kpi_id), gap = k.arah === 'naik' ? Number(r.target) - Number(r.capaian) : Number(r.capaian) - Number(r.target); let score = Math.min(1.2, k.arah === 'naik' ? Number(r.capaian) / Number(r.target) : Number(r.target) / Math.max(Number(r.capaian), .00001)); return { gap, score, weighted: score * Number(k.bobot || r.bobot || 0) / 100 } }
function getResults(period) { return DATA.karyawan.map(e => { let rs = DATA.kpi_records.filter(r => r.karyawan_id === e.karyawan_id && r.periode === period); let valid = rs.map(r => ({ r, s: scoreRecord(r) })).filter(x => x.s); let weight = valid.reduce((a, x) => a + Number(kpiInfo(x.r.kpi_id).bobot || x.r.bobot || 0), 0); let score = weight ? valid.reduce((a, x) => a + x.s.weighted, 0) / (valid.reduce((a, x) => a + Number(kpiInfo(x.r.kpi_id).bobot || x.r.bobot || 0), 0) / 100) : null; let worst = valid.slice().sort((a, b) => b.s.gap - a.s.gap)[0]; return { ...e, score, count: valid.length, worst: worst ? { ...worst.r, ...worst.s, info: kpiInfo(worst.r.kpi_id) } : null } }) }
function status(s) { if (s === null) return ['Tidak dinilai', 'mid']; if (s >= 1) return ['Tinggi', 'high']; if (s >= .9) return ['Sedang', 'mid']; return ['Rendah', 'low'] }
function showPage(p) { document.querySelectorAll('.page').forEach(x => x.classList.remove('active')); $('page-' + p).classList.add('active'); document.querySelectorAll('.nav button').forEach(x => x.classList.toggle('active', x.dataset.page === p)); let names = { dashboard: 'Dashboard', kpi: 'Data KPI', indikator: 'Indikator KPI', rekomendasi: 'Rekomendasi', monitoring: 'Progress Monitoring' }; $('topTitle').textContent = names[p]; $('crumb').textContent = names[p]; if (p === 'kpi') renderKpiTable(); if (p === 'indikator') renderIndicators(); if (p === 'rekomendasi') renderRecommendations(); if (p === 'monitoring') renderMonitoring() }
document.querySelectorAll('.nav button').forEach(b => b.onclick = () => showPage(b.dataset.page));
function renderDashboard() { let period = $('periodSelect').value; state.period = period; let res = getResults(period), sc = res.filter(x => x.score !== null), avg = sc.length ? sc.reduce((a, x) => a + x.score, 0) / sc.length : 0, low = sc.filter(x => x.score < .9).length, gaps = DATA.kpi_records.filter(r => r.periode === period && scoreRecord(r)).filter(r => scoreRecord(r).gap > 0).length; let recs = DATA.rekomendasi.filter(r => r.periode === period); let cards = [['Total karyawan', DATA.karyawan.length, 'Profil fiktif untuk uji prototipe', '♙'], ['Rata-rata skor', fmt(avg * 100) + '%', 'Skor terbobot periode ' + period, '◷'], ['Perlu perhatian', low, 'Karyawan dengan skor < 90%', '⚑'], ['Rekomendasi tercatat', recs.length, 'Rekomendasi pada periode ini', '✦']]; $('stats').innerHTML = cards.map(c => `<div class="card"><div class="stathead">${c[0]}<span class="staticon">${c[3]}</span></div><div class="statnum">${c[1]}</div><div class="statfoot">${c[2]}</div></div>`).join(''); let periods = ['2026-T1', '2026-T2', '2026-T3']; let avgs = periods.map(p => { let a = getResults(p).filter(x => x.score !== null); return a.length ? a.reduce((s, x) => s + x.score, 0) / a.length * 100 : 0 }); $('trendChart').innerHTML = '<div class="bars">' + avgs.map((v, i) => `<div class="barcol"><span class="barval">${fmt(v, 0)}%</span><div class="bar" style="height:${Math.max(3, Math.min(100, v / 120 * 100))}%"></div><span class="barlabel">${periods[i]}</span></div>`).join('') + '</div>'; let counts = { Tinggi: sc.filter(x => x.score >= 1).length, Sedang: sc.filter(x => x.score >= .9 && x.score < 1).length, Rendah: sc.filter(x => x.score < .9).length }; let total = Object.values(counts).reduce((a, b) => a + b, 0) || 1; let t = counts.Tinggi / total * 100, m = counts.Sedang / total * 100, l = counts.Rendah / total * 100; $('donut').style.background = `conic-gradient(#27b79f 0 ${t}%,#4f7ff0 ${t}% ${t + m}%,#e35e67 ${t + m}% 100%)`; $('distLegend').innerHTML = [['Tinggi', counts.Tinggi, '#27b79f'], ['Sedang', counts.Sedang, '#4f7ff0'], ['Rendah', counts.Rendah, '#e35e67']].map(x => `<div class="legenditem"><span><i class="dot" style="background:${x[2]}"></i>${x[0]}</span><b>${x[1]}</b></div>`).join(''); renderPriority() }
function renderPriority() { let res = getResults($('periodSelect').value).filter(x => x.worst).sort((a, b) => (a.score ?? 9) - (b.score ?? 9)); let q = ($('dashSearch').value || '').toLowerCase(); res = res.filter(x => (x.karyawan_id + ' ' + x.jabatan + ' ' + x.unit).toLowerCase().includes(q)).slice(0, 12); $('priorityBody').innerHTML = res.map(x => { let st = status(x.score); return `<tr><td><div class="emp"><div class="miniavatar">${x.karyawan_id.slice(-3)}</div><div><b>${x.karyawan_id}</b><div class="muted">${x.unit}</div></div></div></td><td>${x.jabatan}</td><td><span class="progress"><i style="width:${Math.min(100, (x.score || 0) / 1.2 * 100)}%"></i></span><b>${fmt((x.score || 0) * 100)}%</b></td><td>${x.worst.info.nama_kpi}</td><td>${fmt(x.worst.gap)} ${x.worst.info.satuan === 'persen' ? 'poin' : ''}</td><td><span class="status ${st[1]}">${st[0]}</span></td></tr>` }).join('') || '<tr><td colspan="6" class="empty">Tidak ada data yang cocok.</td></tr>' }
function renderKpiTable() { let p = $('kpiPeriod').value, q = ($('kpiSearch').value || '').toLowerCase(); let rs = DATA.kpi_records.filter(r => r.periode === p).filter(r => { let k = kpiInfo(r.kpi_id), e = DATA.karyawan.find(x => x.karyawan_id === r.karyawan_id); return (r.karyawan_id + ' ' + (e?.jabatan || '') + ' ' + k.nama_kpi).toLowerCase().includes(q) }); $('recordCount').textContent = rs.length + ' rekaman pada ' + p; $('kpiBody').innerHTML = rs.map(r => { let k = kpiInfo(r.kpi_id), s = scoreRecord(r); return `<tr><td>${r.record_id}</td><td><b>${r.karyawan_id}</b></td><td>${k.nama_kpi}<div class="muted">${r.kpi_id}</div></td><td>${fmt(r.target)} ${k.satuan || ''}</td><td>${r.capaian == null ? '—' : fmt(r.capaian)} ${k.satuan || ''}</td><td>${s ? fmt(s.gap) + ' ' + (k.satuan === 'persen' ? 'poin' : '') : '—'}</td><td>${s ? fmt(s.score * 100) + '%' : 'Tidak dinilai'}</td></tr>` }).join('') || '<tr><td colspan="7" class="empty">Tidak ada rekaman.</td></tr>' }
function renderIndicators() { let q = ($('indSearch').value || '').toLowerCase(); let all = [...DATA.kpi_master, ...state.extraIndicators].filter(k => (k.kpi_id + ' ' + k.nama_kpi + ' ' + k.jabatan).toLowerCase().includes(q)); $('indicatorGrid').innerHTML = all.map(k => `<div class="indcard"><div class="indtop"><span class="indcode">${k.kpi_id}</span><span class="status ${k.standar_jelas === false ? 'mid' : 'high'}">${k.standar_jelas === false ? 'Perlu ditinjau' : 'Aktif'}</span></div><div class="indname">${k.nama_kpi}</div><div class="indmeta">${k.jabatan} · ${k.satuan}</div><div class="indtarget"><span>Target standar</span><b>${fmt(k.target_standar)} ${k.satuan === 'persen' ? '%' : k.satuan || ''}</b></div><div class="indtarget"><span>Bobot</span><b>${fmt(k.bobot)}%</b></div><div class="indtarget"><span>Arah penilaian</span><b>${k.arah === 'naik' ? '↑ Semakin tinggi' : '↓ Semakin rendah'}</b></div></div>`).join('') }
function openModal() { $('modal').classList.add('show') } function closeModal() { $('modal').classList.remove('show') }
function addIndicator() { let code = $('fCode').value.trim().toUpperCase(), name = $('fName').value.trim(), role = $('fRole').value, unit = $('fUnit').value, dir = $('fDirection').value, w = Number($('fWeight').value), target = Number($('fTarget').value); if (!code || !name || !Number.isFinite(target) || w < 1 || w > 100) { alert('Lengkapi kode, nama, target, dan bobot 1–100%.'); return } if ([...DATA.kpi_master, ...state.extraIndicators].some(x => x.kpi_id === code)) { alert('Kode indikator sudah digunakan.'); return } state.extraIndicators.push({ kpi_id: code, jabatan: role, nama_kpi: name, satuan: unit, arah: dir, bobot: w, target_standar: target, standar_jelas: false, deskripsi_standar: 'Indikator tambahan pada prototipe' }); closeModal(); renderIndicators(); alert('Indikator ditambahkan ke sesi prototipe. Belum tersimpan ke file Excel atau server.') }
function renderRecommendations() { let rs = DATA.rekomendasi; $('recStats').innerHTML = [['Total rekomendasi', rs.length], ['Disetujui', rs.filter(x => (x.keputusan_manusia || '').includes('Disetujui')).length], ['Perlu tinjauan', rs.filter(x => !x.keputusan_manusia || x.keputusan_manusia.includes('Ditinjau')).length], ['Periode data', '2026-T3']].map((x, i) => `<div class="card"><div class="stathead">${x[0]}<span class="staticon">${['✦', '✓', '◷', '▦'][i]}</span></div><div class="statnum" style="font-size:${i === 3 ? '21' : '29'}px">${x[1]}</div><div class="statfoot">${i === 3 ? 'Basis data fiktif' : 'Berdasarkan lembar rekomendasi'}</div></div>`).join(''); $('recBody').innerHTML = rs.map(r => `<tr><td><b>${r.rec_id}</b></td><td>${r.karyawan_id}</td><td>${r.kpi_utama}</td><td><b>${r.opsi_1_jenis}:</b> ${r.opsi_1_isi}<br><b>${r.opsi_2_jenis}:</b> ${r.opsi_2_isi}<br><b>${r.opsi_3_jenis}:</b> ${r.opsi_3_isi}</td><td><span class="status ${String(r.keputusan_manusia || '').includes('Disetujui') ? 'high' : 'mid'}">${r.keputusan_manusia || 'Belum ditinjau'}</span><div class="muted">Pilihan: ${r.opsi_dipilih || '—'}</div></td><td>${r.ditinjau_oleh || '—'}</td></tr>`).join('') }
function renderMonitoring() { let rs = DATA.tindak_lanjut, done = rs.filter(x => x.capaian_periode_berikut !== null && x.capaian_periode_berikut !== '').length; $('monitorStats').innerHTML = [['Tindak lanjut', rs.length], ['Sudah dievaluasi', done], ['Belum dievaluasi', rs.length - done], ['Periode evaluasi', '2026-T4']].map((x, i) => `<div class="card"><div class="stathead">${x[0]}<span class="staticon">${['↗', '✓', '◷', '▦'][i]}</span></div><div class="statnum" style="font-size:${i === 3 ? '21' : '29'}px">${x[1]}</div><div class="statfoot">Pemantauan tindak lanjut KPI</div></div>`).join(''); $('monitorBody').innerHTML = rs.map(r => { let k = kpiInfo(r.kpi_sasaran); return `<tr><td><b>${r.tl_id}</b></td><td>${r.karyawan_id}</td><td style="white-space:normal;min-width:210px">${r.tindakan_dipilih}</td><td>${r.kpi_sasaran}</td><td>${r.nilai_awal_2026_T3 == null ? '—' : fmt(r.nilai_awal_2026_T3)}</td><td>${fmt(r.target_perbaikan)} ${k.satuan || ''}</td><td>${r.capaian_periode_berikut == null ? 'Belum diisi' : fmt(r.capaian_periode_berikut)}</td><td><span class="status ${r.capaian_periode_berikut == null ? 'mid' : 'high'}">${r.capaian_periode_berikut == null ? 'Belum dievaluasi' : 'Sudah diisi'}</span></td></tr>` }).join('') }
function downloadCSV() { let p = $('kpiPeriod').value, rs = DATA.kpi_records.filter(r => r.periode === p); let lines = [['ID', 'Karyawan', 'Periode', 'ID KPI', 'Nama indikator', 'Target', 'Capaian', 'Gap', 'Skor pencapaian']]; rs.forEach(r => { let k = kpiInfo(r.kpi_id), s = scoreRecord(r); lines.push([r.record_id, r.karyawan_id, r.periode, r.kpi_id, k.nama_kpi, r.target, r.capaian, s?.gap ?? '', s ? Math.round(s.score * 100) + '%' : '']) }); let csv = lines.map(r => r.map(x => '"' + String(x ?? '').replaceAll('"', '""') + '"').join(',')).join('\r\n'); let a = document.createElement('a'); a.href = URL.createObjectURL(new Blob(['\ufeff' + csv], { type: 'text/csv;charset=utf-8;' })); a.download = 'KINERJAAI_' + p + '.csv'; a.click(); URL.revokeObjectURL(a.href) }
$('periodSelect').onchange = renderDashboard; $('kpiPeriod').onchange = renderKpiTable; renderDashboard(); renderIndicators();
